INSERT INTO `faqs` VALUES (1,'2026-10-22 13:14:24','2026-10-22 13:14:24',1,5,'Як підібрати розмір шкарпеток?','<p>Орієнтуйтесь на розмір взуття: 36–38 — розмір 23–25, 39–42 — 25–27, 43–46 — 27–29. Таблиця розмірів є на сторінці кожного товару.</p>'),(2,'2026-10-22 13:14:24','2026-10-22 13:14:24',1,4,'Що означає DEN у колготках?','<p>DEN — щільність нитки. 8–20 DEN — тонкі літні, 30–40 — універсальні на щодень, 70 і більше — щільні та теплі для холодної пори.</p>'),(3,'2026-10-22 13:14:24','2026-10-22 13:14:24',1,3,'Скільки коштує і як довго йде доставка?','<p>Відправляємо щодня, доставка Новою поштою займає 1–2 дні. Від 800 ₴ — безкоштовно, інакше — за тарифами перевізника.</p>'),(4,'2026-10-22 13:14:24','2026-10-22 13:14:24',1,2,'Чи можна обміняти або повернути товар?','<p>Так, протягом 14 днів, якщо виріб не був у використанні та збережено упаковку. Білизна відповідно до законодавства обміну не підлягає.</p>'),(5,'2026-10-22 13:14:24','2026-10-22 13:14:24',1,1,'Як прати, щоб шкарпетки довше служили?','<p>Вивертайте на виворіт, періть при 30–40 °C у делікатному режимі, не використовуйте відбілювачі та не сушіть на батареї.</p>');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;

