INSERT INTO `letter_templates` VALUES (1,'2026-10-22 13:14:32','2026-10-22 13:14:32','feedback',NULL,NULL,NULL,'New feedback','\n            <p>User {{ $user_name}} {{ $user_email}} added new feedback.</p>\n\n            <p>Message:{{ $message }}</p>\n        '),(2,'2026-10-22 13:14:32','2026-10-22 13:14:32','password_reset',NULL,NULL,NULL,'Reset password','\n           <h2>Password recovery</h2>\n\n        <p>\n        You received this email because there was a request to reset your password.\n        </p>\n\n        <p>\n        <a href=\"{{ $reset_url }}\">\n        Change password\n        </a>\n        </p>\n\n        <p>\n        If you did not make this request, simply ignore the letter.\n        </p>\n        '),(3,'2026-10-22 13:14:32','2026-10-22 13:14:32','registration',NULL,NULL,NULL,'Welcome! Your account details','\n        <h2>Welcome, {{ $user_name }}</h2>\n\n        <p>\n        Your account has been created.\n        </p>\n\n        <p>\n        Email: {{ $user_email }}<br>\n        Password: {{ $user_password }}\n        </p>\n\n        <p>\n        <a href=\"{{ $login_url }}\">\n        Log in\n        </a>\n        </p>\n        '),(4,'2026-10-22 13:14:32','2026-10-22 13:14:32','order_created',NULL,NULL,NULL,'Order #{{ $order_number }} created','\n        <h2>Thank you for your order</h2>\n\n        <p>\n        Order number: {{ $order_number }}<br>\n        Total amount: {{ $total_amount }}\n        </p>\n\n        <p>\n        <a href=\"{{ $order_url }}\">\n        View your order\n        </a>\n        </p>\n        ');
