/*!40000 ALTER TABLE `pages` DISABLE KEYS */;
INSERT INTO `pages` VALUES (1,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,0,1,100,'index','Головна','','Nosi — шкарпетки, колготки та білизна з доставкою по Україні','Інтернет-магазин шкарпеток, колготок і білизни: оригінальні бренди, доставка Новою поштою, обмін 14 днів.','[{\"data\": {\"style\": \"default\", \"title\": \"Інтернет-магазин шкарпеток, колготок та білизни Nosi\", \"content\": \"<p>Nosi — це інтернет-магазин, де легко підібрати шкарпетки, колготки та білизну для всієї родини. У каталозі зібрані моделі на кожен день, для спорту, офісу та особливих подій — від базових бавовняних пар до теплих вовняних і фантазійних колготок.</p><h3>Шкарпетки для жінок, чоловіків і дітей</h3><p>Ми пропонуємо класичні, короткі та високі шкарпетки, сліди, спортивні та термошкарпетки. Бавовна з еластаном тримає форму після багатьох прань, а вовна і кашемір зігріють навіть у морози.</p><h3>Колготки та панчохи будь-якої щільності</h3><p>Тонкі колготки 15–20 DEN для літа, універсальні 40 DEN для щоденного образу, щільні 100–200 DEN для зими. Окремо — панчохи, гольфи, моделі з візерунком і корекційні колготки.</p><h3>Чому обирають нас</h3><ul><li>оригінальна продукція від офіційних постачальників;</li><li>понад 3 000 моделей у наявності на складі;</li><li>відправка в день замовлення до 16:00;</li><li>обмін протягом 14 днів.</li></ul><h3>Доставка по всій Україні</h3><p>Доставляємо Новою поштою та Укрпоштою у будь-яке місто: Київ, Львів, Харків, Одеса, Дніпро та інші. Замовлення можна оплатити онлайн карткою або при отриманні.</p><p>Підписуйтесь на розсилку, щоб першими дізнаватися про новинки та сезонні розпродажі.</p>\"}, \"type\": \"text\"}]'),(2,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,1,0,1,99,'news','Новини','news','Новини','Новини',NULL),(3,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,1,0,1,98,'feedback','Зворотний зв’язок','feedback','Зворотний зв’язок','Зворотний зв’язок',NULL),(4,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,1,0,1,97,'shop','Каталог','shop','Каталог','Каталог шкарпеток, колготок і білизни Nosi.',NULL),(5,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,1,0,0,96,'shop_cart','Кошик','cart','Кошик','Кошик',NULL),(6,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,0,0,95,'user_auth','Вхід','auth','Вхід','Вхід',NULL),(7,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,0,0,94,'profile','Кабінет','profile','Кабінет','Кабінет',NULL),(8,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,1,1,93,'page_text','Доставка та оплата','dostavka-ta-oplata','Доставка та оплата','Доставка та оплата — інтернет-магазин Nosi.','[{\"data\": {\"style\": \"default\", \"title\": null, \"content\": \"<p>Відправляємо щодня Новою поштою та Укрпоштою. Від 800 ₴ доставка безкоштовна. Оплата карткою онлайн або при отриманні.</p>\"}, \"type\": \"text\"}]'),(9,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,1,1,92,'page_text','Обмін і повернення','obmin-i-povernennia','Обмін і повернення','Обмін і повернення — інтернет-магазин Nosi.','[{\"data\": {\"style\": \"default\", \"title\": null, \"content\": \"<p>Обмін і повернення протягом 14 днів, якщо виріб не був у використанні та збережено упаковку.</p>\"}, \"type\": \"text\"}]'),(10,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,1,1,91,'page_text','Таблиця розмірів','tablytsia-rozmiriv','Таблиця розмірів','Таблиця розмірів — інтернет-магазин Nosi.','[{\"data\": {\"style\": \"default\", \"title\": null, \"content\": \"<p>Розмір взуття 36–38 — шкарпетки 23–25, 39–42 — 25–27, 43–46 — 27–29.</p>\"}, \"type\": \"text\"}]'),(11,'2026-10-22 13:14:32','2026-10-22 13:14:32',1,0,0,1,90,'page_text','Політика конфіденційності','polityka-konfidentsiinosti','Політика конфіденційності','Політика конфіденційності — інтернет-магазин Nosi.','[{\"data\": {\"style\": \"default\", \"title\": null, \"content\": \"<p>Ми використовуємо ваші дані лише для обробки замовлень і не передаємо їх третім особам.</p>\"}, \"type\": \"text\"}]');
