INSERT INTO `shop_product_reviews` VALUES (1,'2026-10-19 13:15:44','2026-10-22 13:15:44',1,12,NULL,5,'Олена','Київ',NULL,'Ношу вже третій місяць — жодної затяжки. Сидять ідеально, не сповзають. Замовила ще дві пари про запас.',NULL),(2,'2026-10-16 13:15:44','2026-10-22 13:15:44',1,5,NULL,5,'Андрій','Львів',NULL,'Брав набір на подарунок — гарна коробка, все акуратно. Доставка за день, дуже зручно.',NULL),(3,'2026-10-13 13:15:44','2026-10-22 13:15:44',1,3,NULL,5,'Ірина','Одеса',NULL,'Неймовірно м’які та теплі. Після прання не скаталися й не втратили форму. Рекомендую!',NULL),(4,'2026-10-10 13:15:44','2026-10-22 13:15:44',1,13,NULL,4,'Марія','Харків',NULL,'Тканина приємна, розмір відповідає таблиці. Консультант у Telegram допоміг з вибором.',NULL),(5,'2026-10-07 13:15:44','2026-10-22 13:15:44',1,25,NULL,5,'Дмитро','Дніпро',NULL,'Бігаю в них щодня — нога не потіє, п’ята не натирається. Тепер беру тільки ці.',NULL),(6,'2026-10-04 13:15:44','2026-10-22 13:15:44',1,8,NULL,5,'Катерина','Вінниця',NULL,'Купила доньці, тепер вона не хоче знімати :) Яскраві, якісні, ціна приємна.',NULL);
